#define _GNU_SOURCE

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

/*
 * Audit-container compatibility shim.
 *
 * Lean 4.22's bundled libuv resolves the current executable with
 * readlink("/proc/self/exe").  That specific in-process lookup fails in this
 * sandbox even though the same path is readable by ordinary processes.  For
 * that one pathname, supply the pinned toolchain executable recorded in
 * AUDIT_LEAN_EXEC_PATH.  Delegate every other readlink call directly to the
 * kernel.
 */
ssize_t readlink(const char *pathname, char *buffer, size_t size) {
    const char *forced = getenv("AUDIT_LEAN_EXEC_PATH");
    if (forced != NULL && strcmp(pathname, "/proc/self/exe") == 0) {
        size_t length = strlen(forced);
        size_t copied = length < size ? length : size;
        memcpy(buffer, forced, copied);
        return (ssize_t)copied;
    }
    return syscall(SYS_readlink, pathname, buffer, size);
}

